changeSet.sql:
ALTER TABLE bookings DROP CONSTRAINT ck_bookings_status;
ALTER TABLE bookings ADD CONSTRAINT ck_bookings_status
    CHECK (status IN ('initiated', 'payment_processing', 'confirmed', 'failed', 'cancelled'));

